use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = Vec::new();
    for line in input.as_array().unwrap() {
        let mut current_line = line.as_str().unwrap();
        let mut found = false;
        for &expected in &result {
            if expected == current_line {
                found = true;
                break;
            }
        }
        if !found {
            result.push(current_line);
        }
    }
    serde_json::Value::Array(result)
}
